// ============================================
// EVALUATE DLQ STATUS
// ============================================

const dlqLength = parseInt($input.first().json) || 0;

let severity = 'OK';
if (dlqLength > 10) {
  severity = 'CRITICAL';
} else if (dlqLength > 0) {
  severity = 'WARNING';
}

return [{
  json: {
    dlq_count: dlqLength,
    severity: severity,
    threshold_warning: 1,
    threshold_critical: 10,
    checked_at: new Date().toISOString()
  }
}];

// ============================================
// PREPARE ALERT DATA
// ============================================

const status = $('Evaluate Status').first().json;
const samples = $input.all();

// Extract sample error messages
const sampleErrors = [];
for (const item of samples.slice(0, 5)) {
  const data = item.json;
  sampleErrors.push({
    stream_id: data.id || data[0],
    message: data.data?.message || data.fields?.message || 'Unknown',
    error: data.data?.error || data.fields?.error || 'Unknown error',
    failed_at: data.data?.failed_at || data.fields?.failed_at
  });
}

return [{
  json: {
    alert_type: 'dlq_messages',
    severity: status.severity,
    dlq_count: status.dlq_count,
    sample_errors: sampleErrors,
    sample_errors_json: JSON.stringify(sampleErrors),
    created_at: new Date()
  }
}];

// ============================================
// FORMAT DISCORD MESSAGE
// ============================================

const data = $('Prepare Alert').first().json;
const emoji = data.severity === 'CRITICAL' ? '🚨' : '⚠️';
const color = data.severity === 'CRITICAL' ? 0xFF0000 : 0xFFA500;

// Build sample errors text
let errorsText = '';
for (const err of data.sample_errors.slice(0, 3)) {
  errorsText += `• **${err.stream_id}**: ${err.error}\n`;
}

return [{
  json: {
    embeds: [{
      title: `${emoji} Intent DLQ ${data.severity}`,
      description: `Des messages ont échoué et sont dans la Dead Letter Queue.`,
      color: color,
      fields: [
        {
          name: 'Messages en DLQ',
          value: `${data.dlq_count}`,
          inline: true
        },
        {
          name: 'Seuil critique',
          value: '>10 messages',
          inline: true
        },
        {
          name: 'Action requise',
          value: 'Vérifier les logs et relancer manuellement',
          inline: false
        },
        {
          name: 'Échantillon erreurs',
          value: errorsText || 'Aucun détail disponible',
          inline: false
        }
      ],
      timestamp: new Date().toISOString()
    }]
  }
}];
